import re

from moler.exceptions import ParsingDone
from moler.helpers import convert_to_number

from ta_moler.cmd.shared.nokiaunix.generic_nokia_unix import GenericNokiaUnix


class Twampy(GenericNokiaUnix):
    """Twampy script class."""

    def __init__(self, connection, options=None, prompt=None, newline_chars=None, runner=None):
        """
        Twampy script.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameter with which the command will be executed
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        """
        super(Twampy, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.command_path = "./"
        self.row = 0
        self.current_ret["PARSED_LINES"] = []

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = f"twampy.py {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_bind(line)
                self._parse_transmit(line)
                self._parse_sent(line)
                self._parse_received(line)
                self._parse_reply(line)
            except ParsingDone:
                pass
        return super(Twampy, self).on_new_line(line, is_full_line)

    # 21/02/12 12:09:37,546 DEBUG    bind(addr=10.83.178.211, port=5000, tos=136, ttl=64)
    _re_bind = re.compile(r"^(?P<DATE>.*\s.*)\sDEBUG\s*bind\(addr=(?P<ADDR>.*),\sport=(?P<PORT>\d+),\stos=(?P<TOS>\d+),\sttl=(?P<TTL>\d+)\)$")

    def _parse_bind(self, line):
        if self._regex_helper.search_compiled(Twampy._re_bind, line):
            self.current_ret["ADDR"] = self._regex_helper.group("ADDR")
            self.current_ret["ADDR"] = self._regex_helper.group("ADDR")
            self.current_ret["PORT"] = convert_to_number(self._regex_helper.group("PORT"))
            self.current_ret["TOS"] = convert_to_number(self._regex_helper.group("TOS"))
            self.current_ret["TTL"] = convert_to_number(self._regex_helper.group("TTL"))
            raise ParsingDone

    # 21/02/12 12:09:37,548 DEBUG    transmit: 00000000e3d0e0718c4d87ff3fff
    _re_transmit = re.compile(r"^(?P<DATE>.*\s.*)\sDEBUG\s*transmit:\s(?P<TRANSMIT>.*)$")

    def _parse_transmit(self, line):
        if self._regex_helper.search_compiled(Twampy._re_transmit, line):
            self.current_ret["PARSED_LINES"].append({})
            self.current_ret["PARSED_LINES"][self.row]["DATE"] = self._regex_helper.group("DATE")
            self.current_ret["PARSED_LINES"][self.row]["TRANSMIT"] = self._regex_helper.group("TRANSMIT")
            self.row += 1
            raise ParsingDone

    # 21/02/12 12:09:37,548 INFO     Sent to 10.83.182.238 [sseq=0]
    _re_sent = re.compile(r"^(?P<DATE>.*\s.*)\sINFO\s*Sent\sto\s(?P<ADDR>.*)\s\[sseq=(?P<SSEQ>\d+)]$")

    def _parse_sent(self, line):
        if self._regex_helper.search_compiled(Twampy._re_sent, line):
            self.current_ret["PARSED_LINES"].append({})
            self.current_ret["PARSED_LINES"][self.row]["DATE"] = self._regex_helper.group("DATE")
            self.current_ret["PARSED_LINES"][self.row]["ADDR"] = self._regex_helper.group("ADDR")
            self.current_ret["PARSED_LINES"][self.row]["SSEQ"] = convert_to_number(self._regex_helper.group("SSEQ"))
            self.row += 1
            raise ParsingDone

    # 21/02/12 12:09:37,549 DEBUG    received: 00000005e3d0e06d1da1439900050000e3d0e06d1d887e8400000000e3d0e0
    _re_received = re.compile(r"^(?P<DATE>.*\s.*)\sDEBUG\s*received:\s(?P<RECEIVED>.*)$")

    def _parse_received(self, line):
        if self._regex_helper.search_compiled(Twampy._re_received, line):
            self.current_ret["PARSED_LINES"].append({})
            self.current_ret["PARSED_LINES"][self.row]["DATE"] = self._regex_helper.group("DATE")
            self.current_ret["PARSED_LINES"][self.row]["RECEIVED"] = self._regex_helper.group("RECEIVED")
            self.row += 1
            raise ParsingDone

    # 21/02/12 12:09:37,549 INFO  Reply from 10.83.182.238 [rseq=5 sseq=0 rtt=1.05ms outbound=0.00ms inbound=4433.75ms]
    _re_reply = re.compile(
        r"^(?P<DATE>.*\s.*)\sINFO\s*Reply\sfrom\s(?P<ADDR>.*)\s\[rseq=(?P<RSEQ>\d+)\ssseq="
        r"(?P<SSEQ>\d+)\srtt=(?P<RTT>\d+\.?\d*)ms\soutbound=(?P<OUTBOUND>\d+\.?\d*)ms\sinbound="
        r"(?P<INBOUND>\d+\.?\d*)ms]$"
    )

    def _parse_reply(self, line):
        if self._regex_helper.search_compiled(Twampy._re_reply, line):
            self.current_ret["PARSED_LINES"].append({})
            self.current_ret["PARSED_LINES"][self.row]["DATE"] = self._regex_helper.group("DATE")
            self.current_ret["PARSED_LINES"][self.row]["ADDR"] = self._regex_helper.group("ADDR")
            self.current_ret["PARSED_LINES"][self.row]["RSEQ"] = convert_to_number(self._regex_helper.group("RSEQ"))
            self.current_ret["PARSED_LINES"][self.row]["SSEQ"] = convert_to_number(self._regex_helper.group("SSEQ"))
            self.current_ret["PARSED_LINES"][self.row]["RTT"] = convert_to_number(self._regex_helper.group("RTT"))
            self.current_ret["PARSED_LINES"][self.row]["OUTBOUND"] = convert_to_number(self._regex_helper.group("OUTBOUND"))
            self.current_ret["PARSED_LINES"][self.row]["INBOUND"] = convert_to_number(self._regex_helper.group("INBOUND"))
            self.row += 1
            raise ParsingDone


